    let mut score = post_residual as f64;

    // Penalty for creating small, unusable gaps (1-9) which are hard to fill
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Best-Fit logic: prioritize bins that reach a near-full state (residual 0-5)
    if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead logic: if next_item_size is large, favor bins that leave enough space for it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            // Penalize bins that cannot accommodate the next item if we are running out of bins
            score += 15.0;
        }
    }

    // Harmonic class logic: prioritize bins that align with common factors of the capacity (100)
    // 20, 25, 50 are common divisors; favor creating residuals that are multiples of these
    if post_residual % 20 == 0 || post_residual % 25 == 0 {
        score -= 10.0;
    }

    // Threshold logic for opening new bins: 
    // If we have many open bins, penalize opening a new one unless the fit is perfect
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 35.0;
        }
        // If it's a new bin, neutralize the post_residual penalty so we don't over-penalize 
        // the inherent 100 capacity
        score -= (bin_capacity - item_size) as f64;
    }

    // Adaptive pressure: as the stream progresses, prioritize tighter packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // Scarcity constraint: if this is the only bin that fits, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base strategy: Best Fit (minimize post_residual)
    // We heavily penalize creating small "dead" gaps (e.g., 1-9) that are hard to fill later.
    let dead_space_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post) * 15.0
    } else {
        0.0
    };

    // Lookahead logic: If we know the next item, favor bins that can accommodate it 
    // or leave enough room to avoid opening a new bin unnecessarily.
    let lookahead_mod = if next_item_size > 0 {
        if post >= next_item_size as f64 {
            -5.0 // Reward bins that can fit the next item
        } else {
            5.0  // Penalize bins that block the next item
        }
    } else {
        0.0
    };

    // Dynamic scaling: As the stream progresses, prioritize closing bins (lower mean_residual)
    // to consolidate space, especially if fitting_bins_count is low.
    let progress_weight = progress * 20.0;
    let consolidation_reward = (mean_residual - post) * progress_weight;

    // New bin bias: Only open a new bin if the current best fit is truly abysmal
    // or if we are near the end of the stream and need to clear out remaining items.
    let new_bin_bias = if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            0.0 // Necessary
        } else {
            35.0 + (progress * 10.0) // Penalize opening new bins early
        }
    } else {
        0.0
    };

    post + dead_space_penalty + lookahead_mod + consolidation_reward + new_bin_bias
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize gaps that are too small to fit typical items.
    // If post_residual is in the range [1, 9], it's effectively "dead" space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Open Bins Pressure: Penalize opening new bins when space is available.
    // If this is a new bin (bin_residual == bin_capacity), increase score to discourage opening.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 45.0;
    }

    // 3. Lookahead Sensitivity: If the next item is large, avoid leaving a small gap.
    if next_item_size > 0 && next_item_size > post_residual && post_residual < 20 {
        score += 30.0;
    }

    // 4. Fitting Bin Scarcity: If this is the only bin that fits the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Global Efficiency: If current bin is significantly worse than the mean, penalize.
    if (bin_residual as f64) < mean_residual {
        score += 5.0;
    }

    // 6. Final progression weight: As the stream nears the end, prioritize tight packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

