    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. Mean residual balancing: Penalize placing items that push the bin's residual
    // significantly below the current average, preventing fragmented bins.
    if (post_residual as f64) < mean_residual {
        score += 10.0;
    }

    score
}

